const AUTH_KEY = "whereio_auth";

/**
 * @typedef {{ accessToken: string, refreshToken: string, expiresAt: number, remember: boolean }} StoredAuth
 */

/**
 * @param {{ accessToken: string, refreshToken: string, expiresIn?: number }} tokenBody
 * @param {boolean} remember
 */
export function saveAuth(tokenBody, remember) {
  const expiresInSec = Number(tokenBody.expiresIn);
  const expiresAt =
    Number.isFinite(expiresInSec) && expiresInSec > 0
      ? Date.now() + expiresInSec * 1000
      : Date.now() + 15 * 60 * 1000;

  /** @type {StoredAuth} */
  const data = {
    accessToken: tokenBody.accessToken,
    refreshToken: tokenBody.refreshToken,
    expiresAt,
    remember: !!remember,
  };

  const str = JSON.stringify(data);
  if (remember) {
    localStorage.setItem(AUTH_KEY, str);
    sessionStorage.removeItem(AUTH_KEY);
  } else {
    sessionStorage.setItem(AUTH_KEY, str);
    localStorage.removeItem(AUTH_KEY);
  }
}

/** @returns {StoredAuth | null} */
export function loadAuth() {
  const raw = sessionStorage.getItem(AUTH_KEY) || localStorage.getItem(AUTH_KEY);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (!parsed?.accessToken || !parsed?.refreshToken) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function clearAuth() {
  sessionStorage.removeItem(AUTH_KEY);
  localStorage.removeItem(AUTH_KEY);
}
